/**
 * Hand-maintained schema types for the Phase 1 tables.
 *
 * `src/integrations/supabase/types.ts` is generated by Lovable and is
 * currently empty (the schema did not exist when it last ran). Rather than
 * edit a generated file, the app types against this one. Once the
 * migrations are applied and Lovable regenerates, the two can be merged —
 * the shapes are deliberately identical in style.
 */

export type UserStatus = "invited" | "active" | "suspended" | "locked";
export type RecordStatus = "active" | "inactive";
