export type LocationType = "storage" | "picking" | "receiving" | "dispatch" | "quarantine";
export type NotificationSeverity = "info" | "success" | "warning" | "danger";

type Timestamps = {
  created_at: string;
  updated_at: string;
  created_by: string | null;
  updated_by: string | null;
};

